/**
 * Shared readers of the pass W map tests (W1-I: designNotes, originality, townStandard, bossItems): the canon of
 * `layouts/world_canon.py` (read once through Python), map sources (a stub keeps its header `STUB generated by
 * stubs.py` until its owner builds the map), compiled maps, and the cutscenes inside pass W's anchors.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parse } from 'yaml';
import type { MapData } from '../../src/types/index.js';

export interface CanonRow {
  id: string;
  owner: string;
  kind: string;
  links: Array<[string, string, string]>;
}

let canon: CanonRow[] | null = null;

/** The canon map ids (world_canon.CANON), in canon order. */
export function canonRows(): CanonRow[] {
  if (!canon) {
    const code = 'import json, sys; sys.path.insert(0, "assets-src/tools/layouts"); from world_canon import ROWS; '
      + 'print(json.dumps([{"id": r.id, "owner": r.owner, "kind": r.kind, "links": [list(l) for l in r.links]} for r in ROWS]))';
    canon = JSON.parse(execFileSync('python3', ['-I', '-c', code], { encoding: 'utf-8' })) as CanonRow[];
  }
  return canon;
}

export const STUB_MARK = 'STUB generated by stubs.py';

export function sourcePath(id: string): string {
  return join('assets-src/maps', `${id}.yaml`);
}

export function sourceText(id: string): string | null {
  const p = sourcePath(id);
  return existsSync(p) ? readFileSync(p, 'utf-8') : null;
}

/** A canon map is built when its source exists and has lost the stub header. */
export function isBuilt(id: string): boolean {
  const t = sourceText(id);
  return t !== null && !t.split('\n', 1)[0].includes(STUB_MARK);
}

/** The compiled map the game plays (the 2x build), else the legacy one, else null. */
export function compiledMap(id: string): MapData | null {
  for (const p of [join('assets/maps/ai', `${id}.yaml`), join('assets/maps', `${id}.yaml`)]) {
    if (existsSync(p)) return parse(readFileSync(p, 'utf-8')) as MapData;
  }
  return null;
}

/** QUEST_STRICT=1: a pending (stub) map is a failure, not a skip (INT). */
export const STRICT = process.env.QUEST_STRICT === '1';

/** Cutscene ids written between pass W's anchors in cutscenes.yaml (the act-1 cutscenes keep their lines). */
export function passWCutsceneIds(text = readFileSync('assets/data/cutscenes.yaml', 'utf-8')): Set<string> {
  const out = new Set<string>();
  let inside = false;
  for (const line of text.split('\n')) {
    if (/^# === end /.test(line)) inside = false;
    else if (/^# === .*\(pass W: owned by /.test(line)) inside = true;
    else if (inside) {
      const m = /^- id: ([\w-]+)/.exec(line);
      if (m) out.add(m[1]);
    }
  }
  return out;
}

/** Every line of text an NPC, gate or inspect cell of a map shows (conditional dialog included). */
export function mapLines(map: MapData): string[] {
  const out: string[] = [];
  const add = (d: unknown): void => {
    if (typeof d === 'string') out.push(d);
    else if (Array.isArray(d)) d.forEach(add);
    else if (d && typeof d === 'object') add((d as { text?: unknown }).text);
  };
  for (const n of map.npcs ?? []) add(n.dialog);
  for (const g of map.keyItemGates ?? []) add(g.message);
  for (const s of (map as { inspect?: Array<{ text: unknown }> }).inspect ?? []) add(s.text);
  for (const e of map.scriptedEncounters ?? []) add((e as { message?: unknown }).message);
  return out;
}

const LABELS = ['Concept', 'Distinct', 'Topology'] as const;

/** QUEST 4.6 item 1: the design note's three lines from a source's leading comment block, or the errors. */
export function designNote(text: string): { note: Record<string, string>; errors: string[] } {
  const note: Record<string, string> = {};
  const errors: string[] = [];
  const head: string[] = [];
  for (const line of text.split('\n')) {
    if (!line.startsWith('#')) break;
    head.push(line.replace(/^#\s?/, ''));
  }
  let at = -1;
  for (const label of LABELS) {
    const i = head.findIndex((l) => l.startsWith(`${label}:`));
    if (i < 0) { errors.push(`no ${label}: line`); continue; }
    if (i < at) errors.push(`${label}: out of order`);
    at = i;
    note[label] = head[i].slice(label.length + 1).trim();
    if (!note[label]) errors.push(`${label}: is empty`);
  }
  if (note.Distinct && note.Distinct.split(/[;,]/).map((s) => s.trim()).filter(Boolean).length < 2) {
    errors.push('Distinct: names fewer than 2 features');
  }
  return { note, errors };
}
